import { useEffect, useMemo, useState, type FormEvent } from 'react'
import { Activity, ArrowDownToLine, BadgeCheck, Building2, CalendarDays, Check, CircleHelp, FileBarChart, RefreshCw, Search, ShieldAlert, ShieldCheck, Star, Stethoscope, UserRound, Users, X } from 'lucide-react'
import { doctors as demoDoctors, initialAppointments } from '../data/demo'
