type Section = 'Overview' | 'Appointments' | 'Reviews' | 'Doctors' | 'Patients' | 'Hospitals & clinics' | 'Departments' | 'Session recordings' | 'Support inbox' | 'Audit Log' | 'Traffic & settings'
type Summary = { patient_accounts: number; doctor_accounts: number; pending_doctor_requests: number; requested_appointments: number; confirmed_appointments: number; reviews_awaiting_moderation: number; appointments_today: number; outstanding_invoices: number }
type Profile = { id: string; full_name: string; role: string; account_status: string; created_at: string }
type DoctorRecord = { id: string; user_id: string; specialty: string; qualifications: string; experience_years: number | null; verification_status: string; clinic_name: string | null; department_id: string | null; facility_id: string | null }
type DoctorRequest = { id: string; user_id: string; specialty: string; qualifications: string; experience_years: number | null; biography: string | null; department_id: string | null; status: string; review_note: string | null; created_at: string }
type Department = { id: string; name: string; description: string | null; status: string }
type Facility = { id: string; name: string; facility_type: 'clinic'|'hospital'|'diagnostic_center'; address: string; city: string; state: string; postal_code: string; country: string; phone: string|null; latitude: number|null; longitude: number|null; status: 'active'|'inactive' }
type AdminAppointment = { id: string; patient_id: string; doctor_id: string; scheduled_start: string; status: string; appointment_type: string; reason: string | null; patient_name: string; doctor_name: string; specialty: string }
type Audit = { id: string; actor_id: string | null; actor_name?: string | null; action: string; resource_type: string; resource_id: string | null; occurred_at: string; safe_metadata: Record<string, unknown> | null }
const emptySummary: Summary = { patient_accounts: 0, doctor_accounts: 0, pending_doctor_requests: 0, requested_appointments: 0, confirmed_appointments: 0, reviews_awaiting_moderation: 0, appointments_today: 0, outstanding_invoices: 0 }
const formatDate = (value: string) => new Date(value).toLocaleString(undefined, { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' })
const inr = (value: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value)
function AdminHeading({ title, text }: { title: string; text: string }) { return <header className="admin-page-heading"><div><span className="eyebrow">ADMINISTRATION</span><h1>{title}</h1><p>{text}</p></div></header> }
function AdminEmpty({ children }: { children: React.ReactNode }) { return <div className="admin-workspace-empty"><ShieldCheck size={20}/><span>{children}</span></div> }
type SheetCell = string | number
function xmlEscape(value: string) { return value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;') }
function columnName(index: number) { let value=index+1,name='';while(value){const rem=(value-1)%26;name=String.fromCharCode(65+rem)+name;value=Math.floor((value-1)/26)}return name }
function spreadsheetXml(rows: SheetCell[][]) { const cells=rows.map((row,r)=>`<row r="${r+1}">${row.map((value,c)=>{const ref=`${columnName(c)}${r+1}`;return typeof value==='number'&&Number.isFinite(value)?`<c r="${ref}"><v>${value}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xmlEscape(String(value))}</t></is></c>`}).join('')}</row>`).join('');return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${cells}</sheetData></worksheet>` }
function zipStored(files: {name:string;content:string}[]) {
  const encoder=new TextEncoder(),parts:Uint8Array[]=[],central:Uint8Array[]=[];let offset=0
  const write16=(view:DataView,at:number,value:number)=>view.setUint16(at,value,true),write32=(view:DataView,at:number,value:number)=>view.setUint32(at,value>>>0,true)
  const crc32=(bytes:Uint8Array)=>{let crc=0xffffffff;for(const byte of bytes){crc^=byte;for(let bit=0;bit<8;bit++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^0xffffffff)>>>0}
  for(const file of files){const name=encoder.encode(file.name),data=encoder.encode(file.content),crc=crc32(data);const local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);write32(lv,0,0x04034b50);write16(lv,4,20);write16(lv,6,0x0800);write16(lv,8,0);write32(lv,14,crc);write32(lv,18,data.length);write32(lv,22,data.length);write16(lv,26,name.length);write16(lv,28,0);local.set(name,30);parts.push(local,data)
    const entry=new Uint8Array(46+name.length),cv=new DataView(entry.buffer);write32(cv,0,0x02014b50);write16(cv,4,20);write16(cv,6,20);write16(cv,8,0x0800);write16(cv,10,0);write32(cv,16,crc);write32(cv,20,data.length);write32(cv,24,data.length);write16(cv,28,name.length);write16(cv,30,0);write16(cv,32,0);write16(cv,34,0);write16(cv,36,0);write32(cv,38,0);write32(cv,42,offset);entry.set(name,46);central.push(entry);offset+=local.length+data.length
  }
  const centralSize=central.reduce((total,part)=>total+part.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);write32(ev,0,0x06054b50);write16(ev,8,files.length);write16(ev,10,files.length);write32(ev,12,centralSize);write32(ev,16,offset);write16(ev,20,0);return new Uint8Array([...parts.flatMap(part=>Array.from(part)),...central.flatMap(part=>Array.from(part)),...end])
}
function excelDownload(filename:string,sheets:{name:string;rows:SheetCell[][]}[]) {
  const contentTypes=`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`
  const workbook=`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((sheet,i)=>`<sheet name="${xmlEscape(sheet.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`
  const workbookRels=`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`
  const files=[{name:'[Content_Types].xml',content:contentTypes},{name:'_rels/.rels',content:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'},{name:'xl/workbook.xml',content:workbook},{name:'xl/_rels/workbook.xml.rels',content:workbookRels},...sheets.map((sheet,i)=>({name:`xl/worksheets/sheet${i+1}.xml`,content:spreadsheetXml(sheet.rows)}))]
  const archive=zipStored(files),blob=new Blob([archive.buffer as ArrayBuffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),href=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=href;anchor.download=filename;anchor.click();window.setTimeout(()=>URL.revokeObjectURL(href),1000)
}

export default function AdminWorkspace({ section, isDemo, actorId, actorName, onGo, onNotice }: { section: Section; isDemo: boolean; actorId:string; actorName:string; onGo: (section: Section) => void; onNotice: (message: string) => void }) {
  const [summary, setSummary] = useState<Summary>(emptySummary)
  const [profiles, setProfiles] = useState<Profile[]>([])
  const [doctors, setDoctors] = useState<DoctorRecord[]>([])
  const [requests, setRequests] = useState<DoctorRequest[]>([])
  const [departments, setDepartments] = useState<Department[]>([])
  const [facilities, setFacilities] = useState<Facility[]>([])
  const [facilitySelection, setFacilitySelection] = useState<Record<string,string>>({})
  const [appointments, setAppointments] = useState<AdminAppointment[]>([])
  const [audit, setAudit] = useState<Audit[]>([])
  const [loading, setLoading] = useState(!isDemo)
  const [reloadKey, setReloadKey] = useState(0)
  useEffect(()=>{if(!isDemo)return subscribeDemoAudit(()=>setAudit(readDemoAudit().map(event=>({id:event.id,actor_id:null,actor_name:event.actor_role==='administrator'?'Administrator':event.actor_role==='doctor'?'Doctor':'Patient',action:event.action,resource_type:event.resource_type,resource_id:event.resource_id,occurred_at:event.occurred_at,safe_metadata:null}))))},[isDemo])
  const [loadError, setLoadError] = useState('')
  const [query, setQuery] = useState('')
  const [departmentName, setDepartmentName] = useState('')
  const [departmentDescription, setDepartmentDescription] = useState('')
  const [busyId, setBusyId] = useState('')
  const [editingDepartment, setEditingDepartment] = useState('')
  const [editName, setEditName] = useState('')
  const [editDescription, setEditDescription] = useState('')
  const [facilityDraft, setFacilityDraft] = useState<Omit<Facility,'id'|'status'>>({name:'',facility_type:'clinic',address:'',city:'',state:'',postal_code:'',country:'India',phone:'',latitude:null,longitude:null})
  const [editingFacility, setEditingFacility] = useState('')
  const [facilityEdit, setFacilityEdit] = useState<Partial<Facility>>({})

  useEffect(() => {
    if (isDemo) {
      const demoProfiles: Profile[] = [
        { id:'demo-p0',full_name:'Shubh',role:'patient',account_status:'active',created_at:new Date().toISOString() },
        { id:'demo-0',full_name:'Dr. Shreya',role:'doctor',account_status:'active',created_at:new Date().toISOString() },
        { id:'demo-1',full_name:'Dr. Arjun Mehta',role:'doctor',account_status:'active',created_at:new Date().toISOString() },
        { id:'demo-2',full_name:'Dr. Sarah Thomas',role:'doctor',account_status:'active',created_at:new Date().toISOString() },
        { id:'demo-3',full_name:'Dr. Neel Shah',role:'doctor',account_status:'active',created_at:new Date().toISOString() },
        { id:'demo-admin',full_name:'Ram Rajan Reddy',role:'administrator',account_status:'active',created_at:new Date().toISOString() },
      ]
      setProfiles(demoProfiles)
      setDoctors(demoDoctors.map((d,i)=>({id:d.id,user_id:`demo-${i}`,specialty:d.specialty,qualifications:d.qualifications||'',experience_years:Number.parseInt(d.experience,10)||0,verification_status:'approved',clinic_name:d.clinicName||'',department_id:null,facility_id:`demo-facility-${i}`})))
      setRequests([{id:'demo-request',user_id:'demo-applicant',specialty:'Family medicine',qualifications:'Fictional qualification · sample',experience_years:4,biography:'Fictional doctor application for the administration demo.',department_id:null,status:'pending',review_note:null,created_at:new Date().toISOString()}])
      setDepartments([{id:'demo-dept-1',name:'Primary care',description:'General and family medicine',status:'active'},{id:'demo-dept-2',name:'Cardiology',description:'Heart and vascular care',status:'active'},{id:'demo-dept-3',name:'Dermatology',description:'Skin health',status:'active'}])
      const demoFacilities:Facility[]=demoDoctors.map((d,i)=>({id:`demo-facility-${i}`,name:d.clinicName||`${d.specialty} clinic`,facility_type:'clinic',address:d.address||'Sample address',city:d.city||'Demo city',state:d.state||'Demo region',postal_code:d.postalCode||'000000',country:d.country||'India',phone:null,latitude:d.latitude??null,longitude:d.longitude??null,status:'active'}))
      setFacilities(demoFacilities);setFacilitySelection(Object.fromEntries(demoDoctors.map((d,i)=>[d.id,`demo-facility-${i}`])))
      setAppointments(initialAppointments.map((a,i)=>({id:a.id,patient_id:`demo-p${i}`,doctor_id:`d${i+1}`,scheduled_start:new Date().toISOString(),status:a.status,appointment_type:a.type.toLowerCase().includes('video')?'video':'in_person',reason:'Fictional demo visit',patient_name:['Shubh','Sam Lee · sample','Alex Morgan · sample'][i],doctor_name:a.doctor,specialty:a.specialty})))
      setSummary({...emptySummary,patient_accounts:1,doctor_accounts:4,pending_doctor_requests:1,requested_appointments:1,confirmed_appointments:1,reviews_awaiting_moderation:0,appointments_today:2,outstanding_invoices:0})
      const savedAudit=readDemoAudit();setAudit(savedAudit.length?savedAudit.map(event=>({id:event.id,actor_id:null,actor_name:event.actor_role==='administrator'?'Administrator':event.actor_role==='doctor'?'Doctor':'Patient',action:event.action,resource_type:event.resource_type,resource_id:event.resource_id,occurred_at:event.occurred_at,safe_metadata:null})):[{id:'demo-audit',actor_id:null,actor_name:'Administrator',action:'Demo workspace opened',resource_type:'demo',resource_id:null,occurred_at:new Date().toISOString(),safe_metadata:{}}])
      setLoading(false); return
    }
    if (!supabase) { setLoading(false); return }
    let active = true
    void (async () => {
      setLoading(true); setLoadError('')
      const [profileResult, doctorResult, requestResult, departmentResult, facilityResult, appointmentResult, summaryResult, auditResult] = await Promise.all([
        supabase!.from('profiles').select('id,full_name,role,account_status,created_at').order('created_at',{ascending:false}).limit(1000),
        supabase!.from('doctor_profiles').select('id,user_id,specialty,qualifications,experience_years,verification_status,clinic_name,department_id,facility_id').limit(1000),
        supabase!.from('doctor_requests').select('id,user_id,specialty,qualifications,experience_years,biography,department_id,status,review_note,created_at').eq('status','pending').order('created_at',{ascending:true}).limit(1000),
        supabase!.from('departments').select('id,name,description,status').order('name'),
        supabase!.from('health_facilities').select('id,name,facility_type,address,city,state,postal_code,country,phone,latitude,longitude,status').order('name').limit(1000),
        supabase!.from('appointments').select('id,patient_id,doctor_id,scheduled_start,status,appointment_type,reason').order('scheduled_start',{ascending:false}).limit(1000),
        supabase!.rpc('admin_dashboard_summary'),
        supabase!.from('audit_logs').select('id,actor_id,action,resource_type,resource_id,occurred_at,safe_metadata').order('occurred_at',{ascending:false}).limit(10),
      ])
      if (!active) return
      const failed = [profileResult.error,doctorResult.error,requestResult.error,departmentResult.error,facilityResult.error,appointmentResult.error,summaryResult.error,auditResult.error].filter(Boolean)
      if (failed.length) setLoadError('Some administration data could not be loaded. Apply the latest migrations and confirm your administrator access.')
      const profileRows=(profileResult.data||[]) as Profile[],doctorRows=(doctorResult.data||[]) as DoctorRecord[]
      setProfiles(profileRows);setDoctors(doctorRows);setFacilitySelection(Object.fromEntries(doctorRows.map(d=>[d.id,d.facility_id||''])));setRequests((requestResult.data||[]) as DoctorRequest[]);setDepartments((departmentResult.data||[]) as Department[]);setFacilities((facilityResult.data||[]) as Facility[]);setSummary((summaryResult.data?.[0]||emptySummary) as Summary);const namesById=new Map(profileRows.map(profile=>[profile.id,profile.full_name]));setAudit(((auditResult.data||[]) as Audit[]).map(event=>({...event,actor_name:event.actor_id?namesById.get(event.actor_id)||'Administrator':'System'})).slice(0,10))
      const patientNames=new Map(profileRows.map(row=>[row.id,row.full_name||'Patient']))
      const doctorsById=new Map(doctorRows.map(row=>[row.id,row]))
      setAppointments(((appointmentResult.data||[]) as any[]).map(row=>{const doctor=doctorsById.get(row.doctor_id);return {...row,patient_name:patientNames.get(row.patient_id)||'Patient',doctor_name:patientNames.get(doctor?.user_id||'')||'Care team',specialty:doctor?.specialty||'Consultation'}}))
      setLoading(false)
    })()
    return () => { active = false }
  }, [isDemo, reloadKey])

  const filteredProfiles = useMemo(()=>profiles.filter(p=>`${p.full_name} ${p.role} ${p.account_status}`.toLowerCase().includes(query.toLowerCase())),[profiles,query])
  const filteredAppointments = useMemo(()=>appointments.filter(a=>`${a.patient_name} ${a.doctor_name} ${a.specialty} ${a.status}`.toLowerCase().includes(query.toLowerCase())),[appointments,query])
  const filteredDoctors = useMemo(()=>doctors.filter(d=>`${profiles.find(p=>p.id===d.user_id)?.full_name||''} ${d.specialty} ${d.clinic_name||''} ${d.verification_status}`.toLowerCase().includes(query.toLowerCase())),[doctors,profiles,query])
  const people = (id:string) => profiles.find(p=>p.id===id)?.full_name||'Applicant'

  const appendActivity = (action:string,resource_type:string,resource_id:string|null) => { if(isDemo){recordDemoActivity('administrator',action,resource_type,resource_id);setAudit(readDemoAudit().map(event=>({id:event.id,actor_id:null,actor_name:event.actor_role==='administrator'?'Administrator':event.actor_role==='doctor'?'Doctor':'Patient',action:event.action,resource_type:event.resource_type,resource_id:event.resource_id,occurred_at:event.occurred_at,safe_metadata:null})));return} setAudit(current=>[{id:`local-${Date.now()}-${Math.random()}`,actor_id:null,actor_name:actorName,action,resource_type,resource_id,occurred_at:new Date().toISOString(),safe_metadata:null},...current].slice(0,10)) }
  const recordDirectActivity = async(action:'department.created'|'department.updated'|'department.status_changed'|'facility.created'|'facility.updated',resource_type:'department'|'health_facility',resource_id:string) => {
    if(!isDemo){if(!supabase)return false;const {error}=await supabase.rpc('admin_record_activity',{target_action:action,target_resource_type:resource_type,target_resource_id:resource_id});if(error){onNotice('The change was saved, but its activity could not be logged. Apply the latest activity log migration.');return false}}
    appendActivity(action,resource_type,resource_id);return true
  }

  const refresh = () => { setLoading(!isDemo); setLoadError(''); setReloadKey(key=>key+1); onNotice(isDemo?'Demo administration data refreshed.':'Administration data refreshed.') }
  const decideDoctor = async (request:DoctorRequest,approve:boolean) => {
    const note=window.prompt(approve?'Optional note for this approval:':'Optional reason for declining this request:')
    if(note===null)return
    if(isDemo){setRequests(current=>current.filter(r=>r.id!==request.id));if(approve){setDoctors(current=>[...current,{id:`demo-approved-${Date.now()}`,user_id:request.user_id,specialty:request.specialty,qualifications:request.qualifications,experience_years:request.experience_years,verification_status:'approved',clinic_name:'',department_id:request.department_id,facility_id:null}]);setSummary(current=>({...current,pending_doctor_requests:Math.max(0,current.pending_doctor_requests-1),doctor_accounts:current.doctor_accounts+1}))}else setSummary(current=>({...current,pending_doctor_requests:Math.max(0,current.pending_doctor_requests-1)}));appendActivity(approve?'doctor.approved':'doctor.rejected','doctor_request',request.id);onNotice(approve?'Demo provider approved in memory.':'Demo request declined in memory.');return}
    if(!supabase)return;setBusyId(request.id);const {error}=await supabase.rpc('review_doctor_request',{target_request:request.id,approve,decision_note:note.trim()||null});setBusyId('');if(error){onNotice('Could not review this application. Refresh and try again.');return}setRequests(current=>current.filter(r=>r.id!==request.id));if(approve){setDoctors(current=>[...current,{id:`approved-${request.id}`,user_id:request.user_id,specialty:request.specialty,qualifications:request.qualifications,experience_years:request.experience_years,verification_status:'approved',clinic_name:'',department_id:request.department_id,facility_id:null}]);setSummary(current=>({...current,pending_doctor_requests:Math.max(0,current.pending_doctor_requests-1),doctor_accounts:current.doctor_accounts+1}))}else setSummary(current=>({...current,pending_doctor_requests:Math.max(0,current.pending_doctor_requests-1)}));appendActivity(approve?'doctor.approved':'doctor.rejected','doctor_request',request.id);onNotice(approve?'Doctor application approved.':'Doctor application declined.')
  }
  const setAccountStatus = async (profile:Profile) => {
    const next=profile.account_status==='active'?'suspended':'active'
    if(!window.confirm(`${next==='suspended'?'Suspend':'Restore'} ${profile.full_name||'this account'}?`))return
    if(isDemo){setProfiles(current=>current.map(p=>p.id===profile.id?{...p,account_status:next}:p));appendActivity('account.status_changed','profile',profile.id);onNotice(`Demo account ${next}.`);return}
    if(!supabase)return;setBusyId(profile.id);const {error}=await supabase.rpc('admin_set_account_status',{target_user:profile.id,new_status:next});setBusyId('');if(error){onNotice('Could not update account access. Check your administrator permissions.');return}setProfiles(current=>current.map(p=>p.id===profile.id?{...p,account_status:next}:p));appendActivity('account.status_changed','profile',profile.id);onNotice(`Account ${next}.`)
  }
  const resolveAppointment = async (appointment:AdminAppointment,resolution:'cancelled'|'rejected') => {
    const reason=window.prompt(`Reason for ${resolution==='cancelled'?'cancelling':'rejecting'} this appointment:`)
    if(reason===null)return;if(!reason.trim()){onNotice('Add a reason before updating an appointment.');return}
    if(isDemo){setAppointments(current=>current.map(a=>a.id===appointment.id?{...a,status:'cancelled'}:a));setSummary(current=>({...current,requested_appointments:Math.max(0,current.requested_appointments-(appointment.status==='requested'?1:0)),confirmed_appointments:Math.max(0,current.confirmed_appointments-(appointment.status==='confirmed'?1:0))}));appendActivity(`appointment.${resolution}`,'appointment',appointment.id);onNotice('Demo appointment updated in memory.');return}
    if(!supabase)return;setBusyId(appointment.id);const {error}=await supabase.rpc('admin_resolve_appointment',{target_appointment:appointment.id,resolution,resolution_note:reason.trim()});setBusyId('');if(error){onNotice('Could not update this appointment. It may already be closed.');return}setAppointments(current=>current.map(a=>a.id===appointment.id?{...a,status:resolution}:a));setSummary(current=>({...current,requested_appointments:Math.max(0,current.requested_appointments-(appointment.status==='requested'?1:0)),confirmed_appointments:Math.max(0,current.confirmed_appointments-(appointment.status==='confirmed'?1:0))}));appendActivity(`appointment.${resolution}`,'appointment',appointment.id);onNotice(`Appointment ${resolution}.`)
  }
  const addDepartment = async (event:FormEvent) => {event.preventDefault();const clean=departmentName.trim();if(!clean)return;if(isDemo){const id=`demo-dept-${Date.now()}`;setDepartments(current=>[...current,{id,name:clean,description:departmentDescription.trim()||null,status:'active'}]);appendActivity('department.created','department',id);setDepartmentName('');setDepartmentDescription('');onNotice('Department added to demo memory.');return}if(!supabase)return;const {data,error}=await supabase.from('departments').insert({name:clean,description:departmentDescription.trim()||null}).select('id,name,description,status').single();if(error||!data){onNotice(error?.code==='23505'?'A department with this name already exists.':'Could not add the department.');return}setDepartments(current=>[...current,data as Department].sort((a,b)=>a.name.localeCompare(b.name)));if(!await recordDirectActivity('department.created','department',data.id))return;setDepartmentName('');setDepartmentDescription('');onNotice('Department added.')}
  const saveDepartment = async (department:Department) => {const name=editName.trim();if(!name)return;if(isDemo){setDepartments(current=>current.map(d=>d.id===department.id?{...d,name,description:editDescription.trim()||null}:d));appendActivity('department.updated','department',department.id);setEditingDepartment('');onNotice('Demo department updated.');return}if(!supabase)return;const {error}=await supabase.from('departments').update({name,description:editDescription.trim()||null}).eq('id',department.id);if(error){onNotice(error.code==='23505'?'A department with this name already exists.':'Could not update department.');return}setDepartments(current=>current.map(d=>d.id===department.id?{...d,name,description:editDescription.trim()||null}:d));if(!await recordDirectActivity('department.updated','department',department.id))return;setEditingDepartment('');onNotice('Department updated.')}
  const toggleDepartment = async (department:Department) => {const status=department.status==='active'?'inactive':'active';if(isDemo){setDepartments(current=>current.map(d=>d.id===department.id?{...d,status}:d));appendActivity('department.status_changed','department',department.id);onNotice(`Demo department ${status}.`);return}if(!supabase)return;const {error}=await supabase.from('departments').update({status}).eq('id',department.id);if(error){onNotice('Could not change the department status.');return}setDepartments(current=>current.map(d=>d.id===department.id?{...d,status}:d));if(!await recordDirectActivity('department.status_changed','department',department.id))return;onNotice(`Department ${status}.`)}

  const addFacility = async (event:FormEvent) => {event.preventDefault();const clean={...facilityDraft,name:facilityDraft.name.trim(),address:facilityDraft.address.trim(),city:facilityDraft.city.trim(),state:facilityDraft.state.trim(),postal_code:facilityDraft.postal_code.trim(),country:facilityDraft.country.trim(),phone:facilityDraft.phone?.trim()||null};if(!clean.name||!clean.address||!clean.city||!clean.state||!clean.postal_code||!clean.country){onNotice('Complete the facility name and full address.');return}if((clean.latitude===null)!==(clean.longitude===null)){onNotice('Enter both map coordinates or leave both blank.');return}if(isDemo){const row:Facility={...clean,id:`demo-facility-${Date.now()}`,status:'active'};setFacilities(current=>[row,...current]);appendActivity('facility.created','health_facility',row.id);setFacilityDraft({name:'',facility_type:'clinic',address:'',city:'',state:'',postal_code:'',country:'India',phone:'',latitude:null,longitude:null});onNotice('Facility added to the demo workspace.');return}if(!supabase)return;const {data,error}=await supabase.from('health_facilities').insert(clean).select('id,name,facility_type,address,city,state,postal_code,country,phone,latitude,longitude,status').single();if(error||!data){onNotice(error?.code==='23505'?'This facility and address already exist.':'Could not add this facility.');return}setFacilities(current=>[data as Facility,...current].sort((a,b)=>a.name.localeCompare(b.name)));if(!await recordDirectActivity('facility.created','health_facility',data.id))return;setFacilityDraft({name:'',facility_type:'clinic',address:'',city:'',state:'',postal_code:'',country:'India',phone:'',latitude:null,longitude:null});onNotice('Facility added to the directory.')}
  const saveFacility = async (facility:Facility) => {const next={...facility,...facilityEdit,name:String(facilityEdit.name??facility.name).trim(),address:String(facilityEdit.address??facility.address).trim(),city:String(facilityEdit.city??facility.city).trim(),state:String(facilityEdit.state??facility.state).trim(),postal_code:String(facilityEdit.postal_code??facility.postal_code).trim(),country:String(facilityEdit.country??facility.country).trim(),phone:String(facilityEdit.phone??facility.phone??'').trim()||null};if(!next.name||!next.address||!next.city||!next.state||!next.postal_code||!next.country){onNotice('Complete the facility name and full address.');return}if((next.latitude===null)!==(next.longitude===null)){onNotice('Enter both map coordinates or leave both blank.');return}if(isDemo){setFacilities(current=>current.map(f=>f.id===facility.id?next:f));appendActivity('facility.updated','health_facility',facility.id);setEditingFacility('');onNotice('Demo facility updated.');return}if(!supabase)return;const {error}=await supabase.from('health_facilities').update({name:next.name,facility_type:next.facility_type,address:next.address,city:next.city,state:next.state,postal_code:next.postal_code,country:next.country,phone:next.phone,latitude:next.latitude,longitude:next.longitude}).eq('id',facility.id);if(error){onNotice(error.code==='23505'?'Another facility already uses this name and address.':'Could not update this facility.');return}setFacilities(current=>current.map(f=>f.id===facility.id?next:f));if(!await recordDirectActivity('facility.updated','health_facility',facility.id))return;setEditingFacility('');onNotice('Facility details updated.')}
  const toggleFacility = async (facility:Facility) => {const status=facility.status==='active'?'inactive':'active';if(isDemo){setFacilities(current=>current.map(f=>f.id===facility.id?{...f,status}:f));if(status==='inactive'){setDoctors(current=>current.map(d=>d.facility_id===facility.id?{...d,facility_id:null}:d));setFacilitySelection(current=>Object.fromEntries(Object.entries(current).map(([id,value])=>[id,value===facility.id?'':value])))}appendActivity('facility.status_changed','health_facility',facility.id);onNotice(`Demo facility ${status}.`);return}if(!supabase)return;setBusyId(facility.id);const {error}=await supabase.rpc('admin_set_facility_status',{target_facility:facility.id,new_status:status});setBusyId('');if(error){onNotice('Could not change the facility status. Apply the latest facility migration.');return}setFacilities(current=>current.map(f=>f.id===facility.id?{...f,status}:f));if(status==='inactive'){setDoctors(current=>current.map(d=>d.facility_id===facility.id?{...d,facility_id:null}:d));setFacilitySelection(current=>Object.fromEntries(Object.entries(current).map(([id,value])=>[id,value===facility.id?'':value])))}appendActivity('facility.status_changed','health_facility',facility.id);onNotice(`Facility ${status}.`)}
  const assignFacility = async (doctor:DoctorRecord) => {const facilityId=facilitySelection[doctor.id]||null;if(facilityId&&!facilities.some(f=>f.id===facilityId&&f.status==='active')){onNotice('Choose an active hospital or clinic.');return}if(isDemo){setDoctors(current=>current.map(d=>d.id===doctor.id?{...d,facility_id:facilityId}:d));appendActivity('doctor.facility_assigned','doctor_profile',doctor.id);onNotice('Doctor connected to the facility in demo memory.');return}if(!supabase)return;setBusyId(doctor.id);const {error}=await supabase.rpc('admin_assign_doctor_facility',{target_doctor:doctor.id,target_facility:facilityId});setBusyId('');if(error){onNotice('Could not connect this doctor to the facility.');return}setDoctors(current=>current.map(d=>d.id===doctor.id?{...d,facility_id:facilityId}:d));appendActivity('doctor.facility_assigned','doctor_profile',doctor.id);onNotice('Doctor connected to the selected facility.')}

  const exportReport=()=>excelDownload('caresync-admin-activity.xlsx',[{name:'Summary',rows:[['CareSync administration summary'],['Metric','Value'],['Patient accounts',summary.patient_accounts],['Doctor accounts',summary.doctor_accounts],['Pending doctor applications',summary.pending_doctor_requests],['Appointment requests',summary.requested_appointments],['Confirmed appointments',summary.confirmed_appointments],['Appointments today',summary.appointments_today],['Reviews awaiting moderation',summary.reviews_awaiting_moderation],['Outstanding invoices (INR)',Number(summary.outstanding_invoices)||0],['Activity rows included',audit.length]]},{name:'Activity Log',rows:[['When','Administrator','Activity','Area','Reference'],...audit.slice(0,10).map(event=>[formatDate(event.occurred_at),event.actor_name||'Administrator',event.action,event.resource_type,event.resource_id||'—'])]}])
  const SearchBar=()=> <label className="admin-search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by name, specialty, or status"/></label>
  const statusPill=(status:string)=><span className={`admin-status-pill ${status}`}>{status}</span>

  if(section==='Overview') return <section className="admin-workspace"><div className="admin-overview-head"><AdminHeading title="Operations overview." text="Monitor CareSync, review provider applications, and manage the care directory."/><div className="admin-overview-actions"><span className={`admin-mode-tag ${isDemo?'demo':''}`}><i/>{isDemo?'Fictional demo':'Connected data'}</span><button className="btn btn-light btn-sm" onClick={refresh}><RefreshCw size={14}/> Refresh</button></div></div>{isDemo&&<div className="admin-demo-note"><ShieldAlert size={15}/> Demo records are fictional. Admin changes here remain in memory and reset after reload.</div>}{loadError&&<div className="admin-demo-note" role="status">{loadError}</div>}
    <div className="admin-summary-grid"><AdminMetric icon={<Users/>} label="Active patients" value={loading?'—':summary.patient_accounts}/><AdminMetric icon={<Stethoscope/>} label="Doctor accounts" value={loading?'—':summary.doctor_accounts}/><AdminMetric icon={<BadgeCheck/>} label="Provider applications" value={loading?'—':summary.pending_doctor_requests} tone="amber"/><AdminMetric icon={<CalendarDays/>} label="Appointment requests" value={loading?'—':summary.requested_appointments} tone="teal"/><AdminMetric icon={<Star/>} label="Reviews to moderate" value={loading?'—':summary.reviews_awaiting_moderation}/><AdminMetric icon={<Activity/>} label="Visits scheduled today" value={loading?'—':summary.appointments_today} tone="teal"/></div>
    <div className="admin-overview-grid"><section className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">ACTION CENTER</span><h2>Items that need attention</h2></div></div><button className="admin-action-row" onClick={()=>onGo('Doctors')}><span className="admin-action-icon amber"><Stethoscope/></span><span><b>Provider applications</b><small>Review professional details and approve or decline requests.</small></span><strong>{summary.pending_doctor_requests}</strong></button><button className="admin-action-row" onClick={()=>onGo('Appointments')}><span className="admin-action-icon"><CalendarDays/></span><span><b>Appointment requests</b><small>Monitor visit requests; doctors make acceptance decisions.</small></span><strong>{summary.requested_appointments}</strong></button><button className="admin-action-row" onClick={()=>onGo('Reviews')}><span className="admin-action-icon peach"><Star/></span><span><b>Patient reviews</b><small>Moderate comments before they appear in provider listings.</small></span><strong>{summary.reviews_awaiting_moderation}</strong></button><button className="admin-action-row" onClick={()=>onGo('Hospitals & clinics')}><span className="admin-action-icon"><Building2/></span><span><b>Facility directory</b><small>Connect verified doctors to active clinics and hospitals.</small></span><strong>{facilities.filter(f=>f.status==='active').length}</strong></button></section><section className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">PLATFORM CONTROLS</span><h2>Manage CareSync</h2></div></div><div className="admin-control-grid"><AdminControl icon={<Building2/>} title="Clinics & hospitals" text={`${facilities.filter(f=>f.status==='active').length} active facilities`} onClick={()=>onGo('Hospitals & clinics')}/><AdminControl icon={<Building2/>} title="Departments" text={`${departments.length} care categories`} onClick={()=>onGo('Departments')}/><AdminControl icon={<UserRound/>} title="Accounts" text="Patient and doctor access" onClick={()=>onGo('Patients')}/><AdminControl icon={<FileBarChart/>} title="Audit Log" text={`Due invoices ${inr(Number(summary.outstanding_invoices)||0)}`} onClick={()=>onGo('Audit Log')}/></div><p className="admin-trust-note"><ShieldCheck size={14}/> Account changes, provider decisions, and appointment resolutions are recorded in the audit trail.</p></section></div>
  </section>

  if(section==='Appointments') return <section className="admin-workspace"><AdminHeading title="Appointments." text="Monitor incoming requests and confirmed visits. Appointment changes require a reason and notify both parties."/>{loadError&&<div className="admin-demo-note">{loadError}</div>}<div className="admin-toolbar"><SearchBar/><span>{filteredAppointments.length} visits loaded</span></div><div className="admin-panel admin-table-panel">{loading?<AdminEmpty>Loading appointments…</AdminEmpty>:filteredAppointments.length?<div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>PATIENT</th><th>DOCTOR / CLINIC</th><th>WHEN</th><th>TYPE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{filteredAppointments.map(a=><tr key={a.id}><td><b>{a.patient_name}</b><small>Visit request</small></td><td><b>{a.doctor_name}</b><small>{a.specialty}</small></td><td>{formatDate(a.scheduled_start)}</td><td>{a.appointment_type.replace('_',' ')}</td><td>{statusPill(a.status)}</td><td>{['requested','confirmed'].includes(a.status)?<div className="admin-row-actions"><button disabled={busyId===a.id} onClick={()=>void resolveAppointment(a,'cancelled')}>Cancel</button>{a.status==='requested'&&<button disabled={busyId===a.id} onClick={()=>void resolveAppointment(a,'rejected')}>Reject</button>}</div>:<span className="admin-muted">—</span>}</td></tr>)}</tbody></table></div>:<AdminEmpty>No appointments match this search.</AdminEmpty>}</div></section>

  if(section==='Doctors') return <section className="admin-workspace"><AdminCredentialReview onNotice={onNotice}/><AdminHeading title="Provider management." text="Review applications, verify professional credentials, and connect approved providers to a clinic or hospital."/>{isDemo&&<div className="admin-demo-note"><ShieldAlert size={15}/>Fictional provider profiles. Approval changes in demo are temporary.</div>}<div className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">APPLICATION QUEUE</span><h2>Applications awaiting review</h2></div><span className="admin-count">{requests.length} pending</span></div>{loading?<AdminEmpty>Loading applications…</AdminEmpty>:requests.length?<div className="admin-application-list">{requests.map(request=><article className="admin-application" key={request.id}><div className="admin-application-head"><div><b>{isDemo?'Demo applicant':people(request.user_id)}</b><small>{request.specialty} · {request.experience_years??'—'} years experience</small></div>{statusPill('pending')}</div><div className="admin-credential"><b>Qualifications</b><p>{request.qualifications}</p></div>{request.biography&&<p className="admin-bio">{request.biography}</p>}<div className="admin-row-actions"><button disabled={busyId===request.id} onClick={()=>void decideDoctor(request,false)}><X size={13}/> Decline</button><button className="approve" disabled={busyId===request.id} onClick={()=>void decideDoctor(request,true)}><Check size={13}/> Approve provider</button></div></article>)}</div>:<AdminEmpty>No provider applications are waiting for review.</AdminEmpty>}</div><div className="admin-panel admin-table-panel"><div className="admin-panel-head"><div><span className="eyebrow">PROVIDER DIRECTORY</span><h2>Current doctor accounts</h2></div><SearchBar/></div>{loading?<AdminEmpty>Loading providers…</AdminEmpty>:<div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>DOCTOR</th><th>SPECIALTY</th><th>CLINIC</th><th>CONNECTED FACILITY</th><th>QUALIFICATIONS</th><th>PROFILE</th></tr></thead><tbody>{filteredDoctors.map(d=><tr key={d.id}><td><b>{people(d.user_id)}</b><small>{d.experience_years??0} years experience</small></td><td>{d.specialty}</td><td>{d.clinic_name||'Not listed'}</td><td><div className="admin-facility-assign"><select aria-label={`Facility for ${people(d.user_id)}`} value={facilitySelection[d.id]||''} onChange={e=>setFacilitySelection(current=>({...current,[d.id]:e.target.value}))}><option value="">No facility</option>{facilities.filter(f=>f.status==='active').map(f=><option key={f.id} value={f.id}>{f.name} · {f.city}</option>)}</select><button disabled={busyId===d.id||facilitySelection[d.id]===d.facility_id||(!facilitySelection[d.id]&&!d.facility_id)} onClick={()=>void assignFacility(d)}>{busyId===d.id?'Saving…':'Connect'}</button></div></td><td className="admin-qualifications">{d.qualifications||'Not listed'}</td><td>{statusPill(d.verification_status)}</td></tr>)}</tbody></table></div>}</div></section>

  if(section==='Hospitals & clinics') return <section className="admin-workspace"><AdminHeading title="Clinics & hospitals." text="Build the connected care directory with facility addresses, contact details, map coordinates, and linked providers."/>{isDemo&&<div className="admin-demo-note"><ShieldAlert size={15}/>These are fictional demo facilities. Changes reset when the demo reloads.</div>}{loadError&&<div className="admin-demo-note">{loadError}</div>}<div className="admin-facility-layout"><form className="admin-panel admin-facility-form" onSubmit={addFacility}><span className="eyebrow">ADD A FACILITY</span><h2>Register clinic or hospital</h2><FacilityFields value={facilityDraft} onChange={setFacilityDraft}/><p className="admin-facility-help">Map coordinates are optional. Add both latitude and longitude to enable precise map directions.</p><button className="btn btn-primary btn-sm"><Building2 size={14}/> Add facility</button></form><div className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">CONNECTED DIRECTORY</span><h2>{facilities.length} facilities</h2></div><span className="admin-count">{facilities.filter(f=>f.status==='active').length} active</span></div>{loading?<AdminEmpty>Loading facilities…</AdminEmpty>:facilities.length?<div className="admin-facility-list">{facilities.map(f=><article className="admin-facility-card" key={f.id}>{editingFacility===f.id?<><FacilityFields value={{...f,...facilityEdit} as Omit<Facility,'id'|'status'>} onChange={value=>setFacilityEdit(value)}/><div className="admin-row-actions"><button onClick={()=>void saveFacility(f)}>Save facility</button><button onClick={()=>setEditingFacility('')}>Cancel</button></div></>:<><div className="admin-facility-card-head"><div className="admin-facility-mark"><Building2 size={17}/></div><div><b>{f.name}</b><small>{f.facility_type.replace('_',' ')} · {f.city}, {f.state}</small></div>{statusPill(f.status)}</div><p>{f.address}, {f.city}, {f.state} {f.postal_code}, {f.country}</p><div className="admin-facility-meta"><span>{f.phone||'Phone not listed'}</span><span>{doctors.filter(d=>d.facility_id===f.id).length} linked doctors</span></div><div className="admin-row-actions"><button onClick={()=>{setEditingFacility(f.id);setFacilityEdit({...f})}}>Edit details</button><button disabled={busyId===f.id} onClick={()=>void toggleFacility(f)}>{busyId===f.id?'Saving…':f.status==='active'?'Deactivate':'Activate'}</button><button onClick={()=>onGo('Doctors')}>Connect doctors</button></div></>}</article>)}</div>:<AdminEmpty>No facilities yet. Register a clinic or hospital to connect providers.</AdminEmpty>}</div></div><div className="admin-panel admin-facility-tip"><span className="admin-action-icon"><ShieldCheck/></span><div><b>Facility addresses power patient discovery</b><p>When a doctor is connected to an active facility, patients can see its saved address and map coordinates in the provider directory. Deactivating a facility clears provider connections, so closed locations stop appearing.</p></div></div></section>

  if(section==='Patients') return <section className="admin-workspace"><AdminHeading title="Account access." text="Search patient and doctor accounts. Suspend access or restore an account when needed."/><div className="admin-demo-note"><ShieldAlert size={15}/>Suspending an account blocks sign-in. Administrators cannot modify their own access or manage other administrator accounts.</div><div className="admin-toolbar"><SearchBar/><span>{filteredProfiles.length} accounts loaded</span></div><div className="admin-panel admin-table-panel">{loading?<AdminEmpty>Loading accounts…</AdminEmpty>:<div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>ACCOUNT HOLDER</th><th>ROLE</th><th>CREATED</th><th>ACCESS</th><th>ACTION</th></tr></thead><tbody>{filteredProfiles.filter(p=>p.role!=='administrator').map(profile=><tr key={profile.id}><td><b>{profile.full_name||'Unnamed account'}</b><small>Member account</small></td><td>{profile.role}</td><td>{formatDate(profile.created_at)}</td><td>{statusPill(profile.account_status)}</td><td><button className={`admin-access-button ${profile.account_status==='active'?'suspend':''}`} disabled={busyId===profile.id} onClick={()=>void setAccountStatus(profile)}>{busyId===profile.id?'Saving…':profile.account_status==='active'?'Suspend':'Restore'}</button></td></tr>)}</tbody></table>{!filteredProfiles.filter(p=>p.role!=='administrator').length&&<AdminEmpty>No patient or doctor accounts match this search.</AdminEmpty>}</div>}</div></section>

  if(section==='Departments') return <section className="admin-workspace"><AdminHeading title="Departments." text="Maintain care categories used in provider profiles and patient discovery."/><div className="admin-department-layout"><form className="admin-panel admin-department-form" onSubmit={addDepartment}><span className="eyebrow">ADD A CATEGORY</span><h2>New department</h2><label>Name<input required maxLength={120} value={departmentName} onChange={e=>setDepartmentName(e.target.value)} placeholder="e.g. Neurology"/></label><label>Description <span>(optional)</span><textarea rows={3} value={departmentDescription} onChange={e=>setDepartmentDescription(e.target.value)} maxLength={500}/></label><button className="btn btn-primary btn-sm"><Building2 size={14}/> Add department</button></form><div className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">DIRECTORY CATEGORIES</span><h2>{departments.length} departments</h2></div></div>{loading?<AdminEmpty>Loading departments…</AdminEmpty>:departments.length?<div className="admin-department-list">{departments.map(department=><article className="admin-department-row" key={department.id}>{editingDepartment===department.id?<><div className="admin-department-edit"><input value={editName} onChange={e=>setEditName(e.target.value)}/><textarea rows={2} value={editDescription} onChange={e=>setEditDescription(e.target.value)}/><div><button onClick={()=>void saveDepartment(department)}>Save</button><button onClick={()=>setEditingDepartment('')}>Cancel</button></div></div></>:<><div><b>{department.name}</b><small>{department.description||'No description added'}</small></div>{statusPill(department.status)}<div className="admin-row-actions"><button onClick={()=>{setEditingDepartment(department.id);setEditName(department.name);setEditDescription(department.description||'')}}>Edit</button><button onClick={()=>void toggleDepartment(department)}>{department.status==='active'?'Deactivate':'Activate'}</button></div></>}</article>)}</div>:<AdminEmpty>No departments yet. Add a category to start the provider directory.</AdminEmpty>}</div></div></section>
  if(section==='Session recordings') return <AdminRecordings isDemo={isDemo} onNotice={onNotice}/>
  if(section==='Support inbox') return <SupportCenter userId={actorId} userName={actorName} role="administrator" isDemo={isDemo}/>

  if(section==='Traffic & settings') return <TrafficSettings isDemo={isDemo}/>

  return <section className="admin-workspace"><div className="admin-overview-head"><AdminHeading title="Audit Log." text="Review platform totals and the ten most recent recorded activities across patient, doctor, and administrator workspaces."/><button className="btn btn-light btn-sm" onClick={exportReport}><ArrowDownToLine size={14}/> Export Excel</button></div>{isDemo&&<div className="admin-demo-note"><ShieldAlert size={15}/>Fictional aggregate data. No patient names or medical details are exported.</div>}{loadError&&<div className="admin-demo-note">{loadError}</div>}<div className="admin-report-grid"><AdminMetric icon={<Users/>} label="Patient accounts" value={loading?'—':summary.patient_accounts}/><AdminMetric icon={<Stethoscope/>} label="Doctor accounts" value={loading?'—':summary.doctor_accounts}/><AdminMetric icon={<CalendarDays/>} label="Visits today" value={loading?'—':summary.appointments_today}/><AdminMetric icon={<CalendarDays/>} label="Confirmed visits" value={loading?'—':summary.confirmed_appointments}/><AdminMetric icon={<FileBarChart/>} label="Outstanding invoices" value={loading?'—':inr(Number(summary.outstanding_invoices)||0)}/></div><div className="admin-panel admin-table-panel"><div className="admin-panel-head"><div><span className="eyebrow">AUDIT TRAIL</span><h2>Latest website activities</h2></div><span className="admin-count">Showing {audit.length} of 10</span></div>{loading?<AdminEmpty>Loading audit events…</AdminEmpty>:audit.length?<div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>WHEN</th><th>ACTOR</th><th>ACTIVITY</th><th>AREA</th><th>REFERENCE</th></tr></thead><tbody>{audit.map(event=><tr key={event.id}><td>{formatDate(event.occurred_at)}</td><td>{event.actor_name||'System'}</td><td><b>{event.action}</b></td><td>{event.resource_type}</td><td className="admin-audit-id">{event.resource_id||'—'}</td></tr>)}</tbody></table></div>:<AdminEmpty>No audit events are available.</AdminEmpty>}</div><div className="admin-trust-note"><CircleHelp size={14}/>The audit log records activity labels and resource references only. It excludes patient names, prescription contents, and clinical notes.</div></section>
}

type TrafficEvent = { id:string; actor_id:string|null; role:string; occurred_at:string }
function TrafficSettings({isDemo}:{isDemo:boolean}) {
  const [windowSize,setWindowSize]=useState<'1h'|'24h'|'7d'>(()=>{try{return (localStorage.getItem('caresync-admin-traffic-window') as '1h'|'24h'|'7d')||'24h'}catch{return '24h'}})
  const [autoRefresh,setAutoRefresh]=useState(()=>{try{return localStorage.getItem('caresync-admin-auto-refresh')==='true'}catch{return false}})
  const [events,setEvents]=useState<TrafficEvent[]>([]);const [loading,setLoading]=useState(false);const [message,setMessage]=useState('')
  const load=async()=>{
    const cutoff=new Date(Date.now()-(windowSize==='1h'?3600000:windowSize==='24h'?86400000:604800000)).toISOString()
    if(isDemo){setEvents(readDemoAudit().filter(event=>event.action==='session.started'&&event.occurred_at>=cutoff).map(event=>({id:event.id,actor_id:null,role:event.actor_role,occurred_at:event.occurred_at})));return}
    if(!supabase)return
    setLoading(true);setMessage('')
    const {data,error}=await supabase.from('audit_logs').select('id,actor_id,occurred_at').eq('action','session.started').gte('occurred_at',cutoff).order('occurred_at',{ascending:false}).limit(1000)
    if(error){setEvents([]);setMessage('Traffic history is unavailable. Apply the latest site audit migration and confirm administrator access.');setLoading(false);return}
    const rows=(data||[]) as {id:string;actor_id:string|null;occurred_at:string}[]
    const ids=[...new Set(rows.flatMap(row=>row.actor_id?[row.actor_id]:[]))]
    const rolesById=new Map<string,string>()
    if(ids.length){const result=await supabase.from('profiles').select('id,role').in('id',ids);for(const profile of result.data||[])rolesById.set(profile.id,profile.role)}
    setEvents(rows.map(row=>({id:row.id,actor_id:row.actor_id,occurred_at:row.occurred_at,role:row.actor_id?rolesById.get(row.actor_id)||'member':'visitor'})));setLoading(false)
  }
  useEffect(()=>{void load()},[windowSize,isDemo])
  useEffect(()=>{if(!autoRefresh)return;const timer=window.setInterval(()=>void load(),60000);return()=>window.clearInterval(timer)},[autoRefresh,windowSize,isDemo])
  const counts={patient:events.filter(event=>event.role==='patient').length,doctor:events.filter(event=>event.role==='doctor').length,administrator:events.filter(event=>event.role==='administrator').length,all:events.length}
  const hourly=Array.from({length:8},(_,index)=>{const end=Date.now()-index*3*3600000;const start=end-3*3600000;return {label:new Date(end).toLocaleTimeString(undefined,{hour:'numeric'}),count:events.filter(event=>new Date(event.occurred_at).getTime()>=start&&new Date(event.occurred_at).getTime()<end).length}}).reverse();const max=Math.max(1,...hourly.map(item=>item.count))
  const saveWindow=(value:'1h'|'24h'|'7d')=>{setWindowSize(value);try{localStorage.setItem('caresync-admin-traffic-window',value)}catch{}}
  const saveRefresh=(value:boolean)=>{setAutoRefresh(value);try{localStorage.setItem('caresync-admin-auto-refresh',String(value))}catch{}}
  return <section className="admin-workspace"><div className="admin-overview-head"><AdminHeading title="Traffic & settings." text="Review recorded sign-ins by role and tune these administrator dashboard preferences."/><button className="btn btn-light btn-sm" onClick={()=>void load()}><RefreshCw size={14}/> Refresh now</button></div>
    {isDemo&&<div className="admin-demo-note"><ShieldAlert size={15}/>Demo mode counts sign-ins recorded in this browser only. Connected mode reads sign-in audit events; this page does not show server CPU or anonymous visitors.</div>}
    <div className="admin-traffic-controls"><label>Activity window<select value={windowSize} onChange={event=>saveWindow(event.target.value as '1h'|'24h'|'7d')}><option value="1h">Past hour</option><option value="24h">Past 24 hours</option><option value="7d">Past 7 days</option></select></label><label className="admin-traffic-toggle"><span><b>Refresh automatically</b><small>Update this view every minute</small></span><input type="checkbox" checked={autoRefresh} onChange={event=>saveRefresh(event.target.checked)}/></label><span className="admin-traffic-setting-note">These view preferences are saved on this device.</span></div>
    {message&&<div className="admin-demo-note" role="status">{message}</div>}<div className="admin-traffic-metrics"><AdminMetric icon={<Activity/>} label="Recorded sign-ins" value={loading?'…':counts.all}/><AdminMetric icon={<Users/>} label="Patient sign-ins" value={loading?'…':counts.patient}/><AdminMetric icon={<Stethoscope/>} label="Doctor sign-ins" value={loading?'…':counts.doctor}/><AdminMetric icon={<ShieldCheck/>} label="Admin sign-ins" value={loading?'…':counts.administrator}/></div>
    <div className="admin-traffic-layout"><section className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">RECORDED SESSION ACTIVITY</span><h2>Activity over time</h2></div><span className="admin-count">3-hour intervals</span></div><div className="admin-traffic-chart">{hourly.map(item=><div className="admin-traffic-column" key={item.label}><span>{item.count}</span><i style={{height:`${Math.max(4,item.count/max*100)}%`}}/><small>{item.label}</small></div>)}</div></section><section className="admin-panel"><div className="admin-panel-head"><div><span className="eyebrow">WORKSPACE MIX</span><h2>By role</h2></div></div>{(['patient','doctor','administrator'] as const).map(role=><div className="admin-role-meter" key={role}><div><b>{role==='administrator'?'Administrator':role.charAt(0).toUpperCase()+role.slice(1)}</b><small>{counts[role]} sign-ins</small></div><span><i style={{width:`${counts.all?counts[role]/counts.all*100:0}%`}}/></span></div>)}</section></div>
    <div className="admin-trust-note"><CircleHelp size={14}/>Counts are successful account sign-ins recorded by CareSync. They do not equal unique website visitors or live concurrent sessions.</div>
  </section>
}

function AdminMetric({icon,label,value,tone='blue'}:{icon:React.ReactNode;label:string;value:string|number;tone?:string}){return <article className="admin-metric"><span className={`admin-metric-icon ${tone}`}>{icon}</span><div><small>{label}</small><b>{value}</b></div></article>}
function AdminControl({icon,title,text,onClick}:{icon:React.ReactNode;title:string;text:string;onClick:()=>void}){return <button className="admin-control" onClick={onClick}><span>{icon}</span><b>{title}</b><small>{text}</small></button>}
function FacilityFields({value,onChange}:{value:Omit<Facility,'id'|'status'>;onChange:(value:Omit<Facility,'id'|'status'>)=>void}){
  const update=(key:keyof Omit<Facility,'id'|'status'>,next:string)=>onChange({...value,[key]:key==='latitude'||key==='longitude'?(next===''?null:Number(next)):next})
  return <div className="admin-facility-fields"><label>Facility name<input required maxLength={180} value={value.name} onChange={e=>update('name',e.target.value)} placeholder="e.g. Riverside Medical Centre"/></label><label>Facility type<select value={value.facility_type} onChange={e=>update('facility_type',e.target.value)}><option value="clinic">Clinic</option><option value="hospital">Hospital</option><option value="diagnostic_center">Diagnostic centre</option></select></label><label className="wide">Street address<input required maxLength={300} value={value.address} onChange={e=>update('address',e.target.value)} placeholder="Building, street and locality"/></label><label>City<input required value={value.city} onChange={e=>update('city',e.target.value)}/></label><label>State / region<input required value={value.state} onChange={e=>update('state',e.target.value)}/></label><label>Postal code<input required value={value.postal_code} onChange={e=>update('postal_code',e.target.value)}/></label><label>Country<input required value={value.country} onChange={e=>update('country',e.target.value)}/></label><label>Phone <span>(optional)</span><input type="tel" value={value.phone||''} onChange={e=>update('phone',e.target.value)}/></label><label>Latitude <span>(optional)</span><input type="number" min="-90" max="90" step="any" value={value.latitude??''} onChange={e=>update('latitude',e.target.value)}/></label><label>Longitude <span>(optional)</span><input type="number" min="-180" max="180" step="any" value={value.longitude??''} onChange={e=>update('longitude',e.target.value)}/></label></div>
}
